interface.signature:

export interface ProfilingQuestion {
  id: string; // Unique identifier for the question
  text: string; // The question text
  answers: {
    text: string; // The answer option text
    next_question_id?: string; // Optional: ID of the next question if branching
  }[];
  // Additional properties for dynamic logic, e.g., conditional_next_question_id
  // This could be a map or a function to determine the next question based on answer
  // For initial implementation, a simple next_question_id in answers is sufficient.
}
